.sn-shell {
  --sn-bg: #0b111d;
  --sn-panel: #101a29;
  --sn-panel-raised: #131f30;
  --sn-line: rgba(154, 180, 205, .13);
  --sn-text: #edf5f4;
  --sn-muted: #91a2b4;
  --sn-dim: #65778b;
  --sn-mint: #7de2c6;
  --sn-coral: #ff806f;
  box-sizing: border-box;
  max-width: 1080px;
  margin: 0 auto;
  padding: clamp(22px, 4vw, 42px) clamp(16px, 3vw, 30px) 36px;
  color: var(--sn-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.sn-shell *, .sn-shell *::before, .sn-shell *::after { box-sizing: border-box; }
.sn-header { display:flex; align-items:flex-end; justify-content:space-between; gap:24px; margin-bottom:25px; }
.sn-heading-copy { min-width:0; }
.sn-eyebrow { display:flex; align-items:center; gap:9px; margin:0 0 9px; color:var(--sn-mint); font:700 10px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing:.19em; }
.sn-live-dot { width:7px; height:7px; border-radius:50%; background:var(--sn-mint); box-shadow:0 0 12px rgba(125,226,198,.65); }
.sn-eyebrow-divider { color:#516577; }
.sn-header h1 { margin:0; font-size:clamp(28px,4vw,38px); line-height:1.13; letter-spacing:-.045em; font-weight:750; }
.sn-subtitle { margin:8px 0 0; color:var(--sn-muted); font-size:13px; line-height:1.6; }
.sn-scoreboard { display:flex; gap:10px; flex-shrink:0; }
.sn-score-card { display:flex; min-width:112px; flex-direction:column; gap:6px; padding:12px 16px 11px; border:1px solid var(--sn-line); border-radius:13px; background:linear-gradient(145deg, rgba(22,35,51,.96), rgba(14,23,36,.96)); }
.sn-score-current { border-color:rgba(125,226,198,.22); }
.sn-score-label { color:var(--sn-muted); font-size:10px; letter-spacing:.04em; }
.sn-score-card strong { font:700 23px/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing:.02em; font-variant-numeric:tabular-nums; }
.sn-score-current strong { color:var(--sn-mint); }
.sn-layout { display:grid; grid-template-columns:minmax(0, 1fr) 254px; gap:18px; align-items:start; }
.sn-main { min-width:0; }
.sn-board-frame { position:relative; width:100%; overflow:hidden; border:1px solid rgba(132,164,190,.2); border-radius:17px; background:var(--sn-bg); box-shadow:0 18px 48px rgba(0,0,0,.28), 0 0 0 5px rgba(125,226,198,.018); }
.sn-board { display:block; width:100%; height:auto; aspect-ratio:1; outline:none; touch-action:none; }
.sn-board:focus-visible { box-shadow:inset 0 0 0 2px var(--sn-mint); }
.sn-overlay { position:absolute; inset:0; display:grid; place-items:center; padding:20px; background:rgba(7,12,20,.68); backdrop-filter:blur(4px); }
.sn-overlay-card { width:min(100%, 340px); padding:27px 25px 25px; border:1px solid rgba(148,182,202,.2); border-radius:17px; background:linear-gradient(145deg, rgba(19,32,47,.97), rgba(12,21,33,.97)); box-shadow:0 24px 70px rgba(0,0,0,.35); text-align:center; }
.sn-overlay-kicker { color:var(--sn-mint); font:700 9px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing:.18em; }
.sn-overlay-card h2 { margin:10px 0 7px; font-size:23px; letter-spacing:-.025em; }
.sn-overlay-card p { max-width:270px; margin:0 auto 19px; color:var(--sn-muted); font-size:12px; line-height:1.65; }
.sn-button { display:inline-flex; align-items:center; justify-content:center; gap:9px; min-height:39px; padding:0 15px; border:1px solid transparent; border-radius:9px; font-family:inherit;font-size:12px;font-weight:650;line-height:1; cursor:pointer; transition:background-color .16s ease, border-color .16s ease, transform .16s ease, color .16s ease; }
.sn-button:hover:not(:disabled) { transform:translateY(-1px); }
.sn-button:active:not(:disabled) { transform:translateY(0); }
.sn-button:focus-visible, .sn-dpad button:focus-visible, .sn-select-wrap select:focus-visible { outline:2px solid var(--sn-mint); outline-offset:3px; }
.sn-button-primary { min-width:142px; color:#071711; background:var(--sn-mint); box-shadow:0 6px 22px rgba(125,226,198,.16); }
.sn-button-primary:hover { background:#9aecd6; }
.sn-button-primary span { font-size:10px; }
.sn-gamebar { display:flex; align-items:center; justify-content:space-between; gap:14px; padding:13px 2px 0; }
.sn-game-actions { display:flex; gap:8px; }
.sn-button-muted { color:#d6e3e5; border-color:var(--sn-line); background:rgba(17,27,41,.8); }
.sn-button-muted:hover:not(:disabled), .sn-button-quiet:hover:not(:disabled) { border-color:rgba(125,226,198,.32); color:var(--sn-mint); }
.sn-button:disabled { opacity:.45; cursor:not-allowed; }
.sn-button-quiet { color:var(--sn-muted); border-color:transparent; background:transparent; }
.sn-status { display:flex; align-items:center; gap:7px; margin:0; color:var(--sn-muted); font-size:11px; }
.sn-status-dot { width:6px; height:6px; border-radius:50%; background:var(--sn-mint); opacity:.8; }
.sn-dpad { display:none; }
.sn-rail { display:grid; gap:12px; }
.sn-panel { padding:17px 16px; border:1px solid var(--sn-line); border-radius:14px; background:linear-gradient(145deg, rgba(17,28,43,.96), rgba(13,22,35,.96)); }
.sn-panel-heading { display:flex; align-items:center; gap:9px; margin-bottom:17px; }
.sn-panel-heading h2 { margin:0; font-size:13px; font-weight:650; letter-spacing:.01em; }
.sn-panel-icon { display:grid; width:25px; height:25px; place-items:center; border:1px solid rgba(125,226,198,.16); border-radius:8px; color:var(--sn-mint); background:rgba(125,226,198,.07); font-size:15px; }
.sn-field-label { display:block; margin:0 0 7px; color:var(--sn-muted); font-size:10px; }
.sn-select-wrap { position:relative; }
.sn-select-wrap select { width:100%; height:38px; appearance:none; padding:0 34px 0 11px; border:1px solid var(--sn-line); border-radius:8px; color:var(--sn-text); background:#0d1725; font-family:inherit;font-size:12px;font-weight:500; cursor:pointer; }
.sn-select-wrap select option { color:var(--sn-text); background:#0d1725; }
.sn-select-wrap > span { position:absolute; top:8px; right:11px; color:var(--sn-muted); pointer-events:none; }
.sn-toggle-row { position:relative; display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:15px; cursor:pointer; }
.sn-toggle-copy { display:grid; gap:4px; }
.sn-toggle-copy strong { font-size:11px; font-weight:600; }
.sn-toggle-copy small { color:var(--sn-dim); font-size:9px; line-height:1.4; }
.sn-toggle-row input { position:absolute; width:1px; height:1px; opacity:0; }
.sn-switch { position:relative; width:33px; height:19px; flex:none; border:1px solid rgba(150,172,192,.2); border-radius:12px; background:#192638; transition:background-color .18s ease; }
.sn-switch::after { position:absolute; top:3px; left:3px; width:11px; height:11px; border-radius:50%; background:#8191a0; content:""; transition:transform .18s ease, background-color .18s ease; }
.sn-toggle-row input:checked + .sn-switch { border-color:rgba(125,226,198,.32); background:rgba(125,226,198,.23); }
.sn-toggle-row input:checked + .sn-switch::after { transform:translateX(14px); background:var(--sn-mint); }
.sn-toggle-row input:focus-visible + .sn-switch { outline:2px solid var(--sn-mint); outline-offset:3px; }
.sn-key-list { display:grid; gap:11px; }
.sn-key-row { display:flex; align-items:center; justify-content:space-between; gap:8px; color:var(--sn-muted); font-size:10px; }
.sn-key-group { display:flex; gap:3px; }
.sn-shell kbd { display:inline-grid; min-width:22px; height:22px; place-items:center; padding:0 5px; border:1px solid rgba(150,172,192,.2); border-bottom-color:rgba(150,172,192,.34); border-radius:5px; color:#ced9df; background:#162335; font:600 9px/1 ui-monospace, SFMono-Regular, Menlo, monospace; box-shadow:0 2px 0 rgba(0,0,0,.16); }
.sn-shell .sn-key-wide { min-width:53px; }
.sn-food-icon { color:var(--sn-coral); border-color:rgba(255,128,111,.2); background:rgba(255,128,111,.08); font-size:10px; }
.sn-rules-panel .sn-panel-heading { margin-bottom:13px; }
.sn-rule-score { display:flex; align-items:center; justify-content:space-between; color:var(--sn-muted); font-size:11px; }
.sn-rule-score strong { color:var(--sn-coral); font:700 18px/1 ui-monospace, SFMono-Regular, Menlo, monospace; }
.sn-rule-score small { font-family:inherit;font-size:10px;font-weight:500;line-height:1; }
.sn-rule-note { margin:11px 0 0; color:var(--sn-dim); font-size:10px; line-height:1.6; }
.sn-storage-note { display:flex; gap:10px; padding:4px 3px; color:var(--sn-mint); }
.sn-storage-note > span { padding-top:2px; font-size:14px; }
.sn-storage-note p { margin:0; color:var(--sn-muted); font-size:9px; line-height:1.65; }
.sn-storage-note strong { color:#c6d5dd; font-size:10px; font-weight:600; }
.sn-extra-slot:empty { display:none; }
@media (max-width: 760px) {
  .sn-shell { padding-top:22px; }
  .sn-header { align-items:flex-start; flex-direction:column; gap:16px; margin-bottom:19px; }
  .sn-scoreboard { width:100%; }
  .sn-score-card { flex:1; min-width:0; padding:10px 13px; }
  .sn-score-card strong { font-size:20px; }
  .sn-layout { grid-template-columns:minmax(0,1fr); gap:17px; }
  .sn-rail { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .sn-rules-panel, .sn-storage-note { grid-column:span 2; }
  .sn-storage-note { padding:3px 4px; }
}
@media (max-width: 430px) {
  .sn-shell { padding-right:13px; padding-left:13px; }
  .sn-subtitle { max-width:310px; font-size:12px; }
  .sn-board-frame { border-radius:12px; }
  .sn-overlay-card { padding:21px 17px; }
  .sn-overlay-card h2 { font-size:20px; }
  .sn-overlay-card p { font-size:11px; }
  .sn-gamebar { align-items:flex-start; flex-direction:column; gap:8px; }
  .sn-dpad { display:flex; align-items:center; justify-content:space-between; gap:20px; margin-top:10px; padding:12px 16px; border:1px solid var(--sn-line); border-radius:13px; background:rgba(16,26,41,.8); }
  .sn-dpad-hint { color:var(--sn-muted); font-size:10px; }
  .sn-dpad-grid { display:grid; grid-template-columns:repeat(3,34px); grid-template-rows:repeat(3,30px); gap:3px; }
  .sn-dpad-grid button { display:grid; place-items:center; padding:0; border:1px solid var(--sn-line); border-radius:7px; color:var(--sn-mint); background:#152337; font-size:17px; cursor:pointer; touch-action:manipulation; }
  .sn-dpad-grid button:active { background:rgba(125,226,198,.2); }
  .sn-dpad-center { display:grid; place-items:center; color:#52677a; font-size:12px; }
  .sn-rail { grid-template-columns:minmax(0,1fr); }
  .sn-rules-panel, .sn-storage-note { grid-column:auto; }
}
@media (prefers-reduced-motion: reduce) {
  .sn-shell *, .sn-shell *::before, .sn-shell *::after { scroll-behavior:auto !important; transition-duration:.01ms !important; animation-duration:.01ms !important; animation-iteration-count:1 !important; }
}

.sn-shell [hidden]{display:none!important}.sn-select-wrap select:disabled{opacity:.55;cursor:default}.sn-toggle-row input:disabled + .sn-switch{opacity:.45}
@media(max-width:760px),(pointer:coarse){.sn-dpad{display:flex;align-items:center;justify-content:center;gap:24px;margin-top:14px;padding:12px;border:1px solid var(--sn-line);border-radius:13px;background:#101a29}.sn-dpad-hint{color:var(--sn-muted);font-size:11px}.sn-dpad-grid{display:grid;grid-template-columns:repeat(3,44px);grid-template-rows:repeat(3,40px);gap:4px}.sn-dpad-grid button{border:1px solid var(--sn-line);border-radius:8px;background:#152337;color:var(--sn-mint);font-size:20px;cursor:pointer;touch-action:manipulation}.sn-dpad-center{display:grid;place-items:center;color:#52677a}}

