function createSnakeGame({size=24,random=Math.random}={}) {
 const vectors={up:{x:0,y:-1},right:{x:1,y:0},down:{x:0,y:1},left:{x:-1,y:0}};
 let snake,food,direction,queue,score,status,wrap;
 const same=(a,b)=>a.x===b.x&&a.y===b.y;
 function placeFood(){const free=[];for(let y=0;y<size;y++)for(let x=0;x<size;x++){const cell={x,y};if(!snake.some(p=>same(p,cell)))free.push(cell);}return free.length?free[Math.min(free.length-1,Math.floor(random()*free.length))]:null;}
 function reset(options={}){const mid=Math.floor(size/2);snake=[0,1,2,3].map(i=>({x:mid-i,y:mid}));direction='right';queue=[];score=0;status='ready';wrap=!!options.wrap;food=placeFood();}
 function start(){if(status==='ready'||status==='paused')status='running';}
 function pause(){if(status==='running')status='paused';}
 function turn(next){if(status!=='running'||!vectors[next]||queue.length>=2)return false;const previous=queue.at(-1)||direction,a=vectors[previous],b=vectors[next];if(previous===next||a.x+b.x===0&&a.y+b.y===0)return false;queue.push(next);return true;}
 function step(){
  if(status!=='running')return;
  if(queue.length)direction=queue.shift();
  const delta=vectors[direction],head={x:snake[0].x+delta.x,y:snake[0].y+delta.y};
  if(wrap){head.x=(head.x+size)%size;head.y=(head.y+size)%size;}
  else if(head.x<0||head.x>=size||head.y<0||head.y>=size){status='lost';return;}
  const eating=!!food&&same(head,food),body=eating?snake:snake.slice(0,-1);
  if(body.some(p=>same(p,head))){status='lost';return;}
  snake.unshift(head);if(eating){score+=10;food=placeFood();if(!food)status='won';}else snake.pop();
 }
 function snapshot(){return {size,snake:snake.map(p=>({...p})),food:food?{...food}:null,direction,score,status,wrap};}
 reset();return {reset,start,pause,turn,step,snapshot};
}

const $=s=>root.querySelector(s), canvas=$('[data-sn-canvas]'),ctx=canvas.getContext('2d');
const game=createSnakeGame(),bestKey='codex-studio-snake-best-v1';
let best=0,storageOK=true,timer=null;
try {const saved=Number(localStorage.getItem(bestKey)||0);if(Number.isSafeInteger(saved)&&saved>=0)best=saved;}catch(_){storageOK=false;}
function saveBest(score){if(score<=best)return;best=score;try{localStorage.setItem(bestKey,String(best));}catch(_){storageOK=false;}}
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function draw(s){
 const size=canvas.width,cell=size/s.size;ctx.clearRect(0,0,size,size);ctx.fillStyle='#0b1520';ctx.fillRect(0,0,size,size);
 ctx.strokeStyle='#1b2d3b';ctx.lineWidth=1;ctx.beginPath();for(let i=1;i<s.size;i++){ctx.moveTo(i*cell,0);ctx.lineTo(i*cell,size);ctx.moveTo(0,i*cell);ctx.lineTo(size,i*cell);}ctx.stroke();
 if(s.food){const x=(s.food.x+.5)*cell,y=(s.food.y+.5)*cell;ctx.save();ctx.shadowColor='#ff9485';ctx.shadowBlur=15;ctx.fillStyle='#ff9485';ctx.beginPath();ctx.arc(x,y,cell*.29,0,Math.PI*2);ctx.fill();ctx.restore();ctx.fillStyle='#ffe8df';ctx.beginPath();ctx.arc(x-2,y-3,cell*.08,0,Math.PI*2);ctx.fill();}
 for(let i=s.snake.length-1;i>=0;i--){const p=s.snake[i],inset=i?2.5:1.5;rounded(p.x*cell+inset,p.y*cell+inset,cell-inset*2,cell-inset*2,i?6:8,i?'#56bca5':'#a6f5d3');}
 const head=s.snake[0],cx=(head.x+.5)*cell,cy=(head.y+.5)*cell,vec={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[s.direction];ctx.fillStyle='#15392f';
 for(const sign of [-1,1]){ctx.beginPath();ctx.arc(cx+vec[0]*cell*.19+vec[1]*sign*cell*.16,cy+vec[1]*cell*.19+vec[0]*sign*cell*.16,cell*.065,0,Math.PI*2);ctx.fill();}
 canvas.setAttribute('aria-label','贪食蛇棋盘，得分 '+s.score+'，长度 '+s.snake.length+'。方向键或 WASD 移动。');
}
function render(){
 const s=game.snapshot();saveBest(s.score);$('[data-sn-score]').textContent=s.score;$('[data-sn-best]').textContent=best;
 $('[data-sn-storage]').textContent=storageOK?'最高分自动保存在当前浏览器':'浏览器存储不可用，最高分仅在本次页面中保留';
 const active=s.status==='running',paused=s.status==='paused';$('[data-sn-overlay]').hidden=active;
 $('[data-sn-pause]').disabled=!active&&!paused;$('[data-sn-pause]').textContent=paused?'继续游戏':'暂停游戏';$('[data-sn-pause]').setAttribute('aria-label',paused?'继续游戏':'暂停游戏');
 $('[data-sn-speed]').disabled=active||paused;$('[data-sn-wrap]').disabled=active||paused;
 const copy={ready:['准备好，出发。','吃掉珊瑚色食物，让小蛇不断长大。','开始游戏','准备就绪 · 选择速度后开始'],paused:['歇一会儿，再继续。','游戏已暂停，准备好后继续。','继续游戏','已暂停 · 按空格或点击继续'],lost:['差一点，再来一局。','本局得到 '+s.score+' 分，下一次会更好。','再来一局','游戏结束 · 撞到了墙壁或自己的身体'],won:['整个世界，都是你。','你填满了棋盘！最终得分 '+s.score+'。','再来一局','恭喜！你已填满整个棋盘']};
 let statusText;
 if(copy[s.status]){const [title,message,action,status]=copy[s.status];$('[data-sn-title]').textContent=title;$('[data-sn-message]').textContent=message;$('[data-sn-start]').textContent=action;statusText=status;}
 else statusText=(s.wrap?'穿墙模式':'经典模式')+' · 吃到食物 +10 分 · 空格暂停';
 if($('[data-sn-status]').textContent!==statusText)$('[data-sn-status]').textContent=statusText;
 draw(s);
}
function stopClock(){if(timer!==null){clearInterval(timer);timer=null;}}
function runClock(){stopClock();const speed=Number($('[data-sn-speed]').value)||125;timer=setInterval(()=>{game.step();const s=game.snapshot();if(s.status!=='running')stopClock();render();},speed);}
function focusBoard(){canvas.focus({preventScroll:true});}
function startNew(){game.reset({wrap:$('[data-sn-wrap]').checked});game.start();runClock();render();focusBoard();}
function startOrResume(){const s=game.snapshot();if(s.status==='paused'){game.start();runClock();render();focusBoard();}else if(s.status!=='running')startNew();}
function togglePause(){if(game.snapshot().status==='running'){game.pause();stopClock();render();}else if(game.snapshot().status==='paused')startOrResume();focusBoard();}
const events=new AbortController();
function listen(el,event,handler,options={}){el.addEventListener(event,handler,{...options,signal:events.signal});}
listen($('[data-sn-start]'),'click',startOrResume);listen($('[data-sn-pause]'),'click',togglePause);listen($('[data-sn-restart]'),'click',startNew);
root.querySelectorAll('[data-sn-dir]').forEach(button=>listen(button,'click',()=>{game.turn(button.dataset.snDir);focusBoard();}));
listen(root,'keydown',e=>{
 if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,button,a,[contenteditable="true"]'))return;
 const keys={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'},direction=keys[e.key]||keys[e.key.toLowerCase()];
 if(direction){e.preventDefault();game.turn(direction);}else if(e.code==='Space'){e.preventDefault();if(!e.repeat)togglePause();}else if(e.key==='Enter'){e.preventDefault();if(!e.repeat)startOrResume();}
});
let gesture=null;
listen(canvas,'pointerdown',e=>{if(!e.isPrimary)return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);focusBoard();});
listen(canvas,'pointerup',e=>{if(!gesture||gesture.id!==e.pointerId)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;gesture=null;if(Math.max(Math.abs(dx),Math.abs(dy))<12)return;game.turn(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'));});
listen(canvas,'pointercancel',()=>{gesture=null;});
listen(document,'visibilitychange',()=>{if(document.hidden&&game.snapshot().status==='running'){game.pause();stopClock();render();}});
render();
return ()=>{stopClock();events.abort();};
